@js:var ref='http://m.1kkk.com/';
var html=String(result||'');
var i=html.indexOf('eval(function(p,a,c,k,e,d)');
var urls=[];
if(i>=0){
  var j=html.indexOf('(',i);
  var depth=0,end=-1;
  for(var p=j;p<html.length;p++){
    var ch=html.charAt(p);
    if(ch==='(')depth++;
    else if(ch===')'){depth--;if(depth===0){end=p;break;}}
  }
  if(end>0){
    var expr=html.substring(j,end+1);
    var unpacked='';
    try{ unpacked=(new Function('return '+expr))(); }catch(e){ unpacked=''; }
    if(typeof unpacked!=='string') unpacked=String(unpacked||'');
    var m=unpacked.match(/newImgs\s*=\s*\[([\s\S]*?)\]/);
    if(m){
      var re=/['"]([^'"]+)['"]/g,q;
      while((q=re.exec(m[1]))){ urls.push(q[1]); }
    }
  }
}
if(!urls.length){
  var re2=/<img[^>]+src="([^"]*(?:cdndm5|\.jpg|\.webp)[^"]*)"/g,q2;
  while((q2=re2.exec(html))){ urls.push(q2[1]); }
}
var hdr='{"headers":{"Referer":"'+ref+'","User-Agent":"Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 Chrome/120 Mobile Safari/537.36"}}';
var out=[];
for(var k=0;k<urls.length;k++){ out.push(urls[k]+','+hdr); }
result=out.join('\n');
